(()=>{if(parent===window||!new URLSearchParams(location.search).has('edit'))return;const origin=location.origin;let enabled=true,selected=null;const page=location.pathname.split('/').pop()||'index.html';const send=(type,payload={})=>parent.postMessage({source:'chao-content',type,page,...payload},origin);function target(key){return [...document.querySelectorAll('[data-edit-key]')].find(e=>e.dataset.editKey===key)}function select(el){document.querySelectorAll('[data-chao-selected]').forEach(n=>n.removeAttribute('data-chao-selected'));selected=el;if(!el)return;el.setAttribute('data-chao-selected','');const cs=getComputedStyle(el),block=el.closest('[data-edit-block]');send('selected',{selection:{key:el.dataset.editKey,kind:el.dataset.editKind,tag:el.tagName,html:el.innerHTML,text:el.innerText||el.textContent,src:el.getAttribute('src'),alt:el.getAttribute('alt')||'',href:el.getAttribute('href'),shared:el.dataset.editKey.startsWith('shared:'),style:{color:cs.color,'font-size':cs.fontSize,'text-align':cs.textAlign,'font-weight':cs.fontWeight,'object-fit':cs.objectFit,'object-position':cs.objectPosition},block:block?{key:block.dataset.editBlock,parent:block.parentElement.dataset.editParent,title:block.querySelector('h1,h2,h3,h4')?.textContent||block.dataset.editBlock}:null}})}document.addEventListener('click',e=>{if(!enabled||e.altKey)return;const el=e.target.closest('[data-edit-key]');if(el){e.preventDefault();e.stopImmediatePropagation();select(el)}},true);document.addEventListener('mouseover',e=>{document.querySelectorAll('[data-chao-hover]').forEach(n=>n.removeAttribute('data-chao-hover'));if(enabled)e.target.closest('[data-edit-key]')?.setAttribute('data-chao-hover','')});document.addEventListener('input',e=>{const el=e.target.closest('[contenteditable=true][data-edit-key]');if(el)send('inline-change',{key:el.dataset.editKey,change:{html:ChaoContent.sanitize(el.innerHTML)}})});document.addEventListener('dblclick',e=>{if(!enabled)return;const el=e.target.closest('[data-edit-kind="text"]');if(!el)return;e.preventDefault();e.stopPropagation();el.contentEditable='true';el.focus();el.addEventListener('blur',()=>{el.removeAttribute('contenteditable');const html=ChaoContent.sanitize(el.innerHTML);send('inline-change',{key:el.dataset.editKey,change:{html}});select(el)},{once:true})},true);addEventListener('message',async e=>{if(e.origin!==origin||e.source!==parent||e.data?.source!=='chao-editor')return;const data=e.data;try{if(data.command==='mode'){enabled=data.enabled;document.body.classList.toggle('chao-editing',enabled)}if(data.command==='select-block'){const block=[...document.querySelectorAll('[data-edit-block]')].find(n=>n.dataset.editBlock===data.key);if(block){block.scrollIntoView({behavior:'instant',block:'start'});select(block.querySelector('[data-edit-key]'))}}if(data.command==='select'){const el=target(data.key);if(el){el.scrollIntoView({behavior:'instant',block:'center'});select(el)}}if(data.command==='apply'){ChaoContent.replace(data.state);await ChaoContent.apply(document,page,{reset:true});if(selected)select(target(selected.dataset.editKey))}if(data.command==='inspect')sendInventory();if(data.command==='clear-selection')select(null)}catch(error){send('error',{message:error.message})}});function sendInventory(){send('ready',{title:document.title,items:[...document.querySelectorAll('[data-edit-key]')].filter(el=>el.dataset.editKind==='image'||(el.innerText||el.textContent||'').trim()).map(el=>({key:el.dataset.editKey,kind:el.dataset.editKind,tag:el.tagName,text:(el.getAttribute('alt')||el.innerText||el.textContent||'').trim().slice(0,90),src:el.tagName==='IMG'?el.getAttribute('src'):null})),blocks:[...document.querySelectorAll('[data-edit-block]')].map(el=>({key:el.dataset.editBlock,parent:el.parentElement.dataset.editParent,title:el.querySelector('h1,h2,h3,h4')?.textContent||el.dataset.editBlock}))})}ChaoContent.ready.then(async()=>{await ChaoContent.apply(document,page);document.body.classList.add('chao-editing');sendInventory()});})();
